export const tokens: readonly Card[] = definitions.map(
  ([id, name, rank, power, pattern, abilityText]) => {
    const offsets = (marks: string) =>
      pattern.flatMap((row, r) =>
        [...row].flatMap((mark, c) =>
          marks.includes(mark) ? [[r - 2, c - 2] as const] : [],
        ),
      );
    return {
      id,
      name,
      rank,
      power,
      reach: offsets("RB"),
      effectOffsets: offsets("EB"),
      abilityText,
      ability: compileAbility(abilityText),
    };
  },
);
export const tokenCard = (id: string) => {
  const card = tokens.find((candidate) => candidate.id === id);
  if (!card) throw new Error("Unknown token: " + id);
  return card;
};
